<template><section class="cost-page"><header class="cost-page-heading"><div><h2>هزینه‌های سربار</h2><p>هزینه‌های ماهانه و مبلغ ثابت هر فروش را مدیریت کنید.</p></div><button class="cost-primary" @click="openCreate">هزینه سربار جدید</button></header><div class="next-step">هزینه ماهانه بین محصولات فعال تقسیم می‌شود؛ هزینه «هر فروش» مستقیماً به بهای هر محصول اضافه می‌شود.</div><div v-if="error" class="cost-notice" role="alert">{{error}} <button @click="load">تلاش مجدد</button></div><div class="overhead-list"><article v-for="item in overheads" :key="item.id"><div><strong>{{item.title}}</strong><small>{{item.kind_display}}</small></div><div><span>مبلغ</span><strong>{{money(item.amount)}}</strong></div><div><span>تخصیص</span><strong>{{item.allocation_method_display}}</strong></div><div><span>تاریخ</span><strong>{{date(item.expense_date)}}</strong></div><span :class="['status',item.is_active?'on':'off']">{{item.is_active?'فعال':'غیرفعال'}}</span><footer><button class="row-action" @click="openEdit(item)">ویرایش</button><button class="danger-action" @click="remove(item)">حذف</button></footer></article><div v-if="loading" class="empty-resource">در حال دریافت هزینه‌ها…</div><div v-else-if="!overheads.length" class="empty-resource">هزینه سرباری ثبت نشده است.</div></div><div class="resource-pagination" v-if="pagination.total_pages>1"><button class="cost-secondary" :disabled="!pagination.has_previous" @click="goPage(pagination.page-1)">قبلی</button><span>صفحه {{number(pagination.page)}} از {{number(pagination.total_pages)}}</span><button class="cost-secondary" :disabled="!pagination.has_next" @click="goPage(pagination.page+1)">بعدی</button></div><OverheadModal v-model="modalOpen" :overhead="editing" :kinds="meta.overhead_kinds" :allocations="meta.allocation_methods" :loading="saving" :server-error="modalError" :field-errors="fieldErrors" @submit="save"/></section></template>
<script setup>import{onMounted,reactive,ref}from'vue';import API from'@/api/product-cost.api.js';import OverheadModal from'@/components/modals/OverheadModal.vue';import{costErrorMessage,formatCostNumber as number,formatMoney as money}from'@/utils/costControl';const overheads=ref([]),editing=ref(null),modalOpen=ref(false),loading=ref(false),saving=ref(false),error=ref(''),modalError=ref(''),fieldErrors=ref({}),meta=reactive({overhead_kinds:[],allocation_methods:[]}),pagination=reactive({page:1,page_size:10,total_pages:1,has_next:false,has_previous:false});async function load(){loading.value=true;error.value='';try{const[metadata,data]=await Promise.all([meta.overhead_kinds.length?Promise.resolve(meta):API.meta(),API.overheads({page:pagination.page,page_size:pagination.page_size})]);Object.assign(meta,metadata);overheads.value=data.results||[];Object.assign(pagination,data)}catch(cause){error.value=costErrorMessage(cause)}finally{loading.value=false}}function openCreate(){editing.value=null;modalError.value='';fieldErrors.value={};modalOpen.value=true}function openEdit(item){editing.value=item;modalError.value='';fieldErrors.value={};modalOpen.value=true}async function save(payload){saving.value=true;modalError.value='';fieldErrors.value={};try{if(editing.value)await API.updateOverhead(editing.value.id,payload);else await API.createOverhead(payload);modalOpen.value=false;await load()}catch(cause){modalError.value=costErrorMessage(cause);fieldErrors.value=cause.cost?.errors||{}}finally{saving.value=false}}async function remove(item){if(!confirm(`هزینه «${item.title}» حذف شود؟`))return;try{await API.deleteOverhead(item.id);await load()}catch(cause){error.value=costErrorMessage(cause)}}function goPage(page){pagination.page=page;load()}const date=value=>value?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{dateStyle:'medium',timeZone:'Asia/Tehran'}).format(new Date(value)):'—';onMounted(load)</script>
<style scoped>.overhead-list{display:grid;gap:8px}.overhead-list article{display:grid;grid-template-columns:minmax(160px,1.3fr) repeat(3,minmax(110px,1fr)) auto auto;align-items:center;gap:12px;padding:13px 15px;background:var(--surface);border:1px solid var(--border);border-radius:11px}.overhead-list article>div{display:grid;gap:3px}.overhead-list span,.overhead-list small{color:var(--muted);font-size:.67rem}.overhead-list strong{font-size:.78rem}.overhead-list footer{display:flex}.overhead-list>.empty-resource{background:var(--surface);border:1px solid var(--border);border-radius:11px}@media(max-width:850px){.overhead-list article{grid-template-columns:repeat(2,minmax(0,1fr))}.overhead-list footer{justify-self:end}}@media(max-width:500px){.overhead-list article{grid-template-columns:1fr}.overhead-list footer{justify-self:start}}</style>
